GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Multi-start greedy + local search for an initial solution, then binary
    search on the KVPR threshold T. For a fixed T, each GPU g has a budget:
    load_g + r <= T * (free_g - size), i.e., remaining budget
    T*free_g - load_g must cover r while memory stays positive. Feasibility
    is checked with best-fit-decreasing (models sorted by r desc, each
    placed on the GPU whose remaining budget best matches r, minimizing
    leftover) plus a few randomized restarts. ~40 bisection iterations keep
    the best feasible placement found. Falls back to greedy if nothing fits.
    """

    def kvpr(load, free):
        return load / free if free > 0 else float('inf')

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            r = model.req_rate / model.slo
            best_idx, best_ratio = None, float('inf')
            for g in range(gpu_num):
                if free[g] - model.model_size > 0:
                    ratio = kvpr(load[g] + r, free[g] - model.model_size)
                    if ratio < best_ratio:
                        best_ratio, best_idx = ratio, g
            if best_idx is None:
                return None, None, None
            placement[best_idx].append(model)
            load[best_idx] += r
            free[best_idx] -= model.model_size
        return placement, free, load

    def refine(placement, free, load):
        # Local search accepting improving moves plus a budgeted number of
        # sideways (equal max KVPR) moves to escape plateaus.
        sideways_budget = 20
        improved = True
        while improved:
            improved = False
            cur_max = max(kvpr(load[g], free[g]) for g in range(gpu_num))
            # Pass 1: single-model moves
            for src in range(gpu_num):
                for model in list(placement[src]):
                    r = model.req_rate / model.slo
                    for dst in range(gpu_num):
                        if dst == src or free[dst] - model.model_size <= 0:
                            continue
                        new_max = max(
                            kvpr(load[src] - r, free[src] + model.model_size),
                            kvpr(load[dst] + r, free[dst] - model.model_size),
                            max(kvpr(load[g], free[g]) for g in range(gpu_num)
                                if g not in (src, dst)),
                        )
                        if new_max < cur_max - 1e-12 or (
                                new_max <= cur_max + 1e-12
                                and sideways_budget > 0):
                            if new_max >= cur_max - 1e-12:
                                sideways_budget -= 1
                            placement[src].remove(model)
                            placement[dst].append(model)
                            load[src] -= r; free[src] += model.model_size
                            load[dst] += r; free[dst] -= model.model_size
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                continue
            # Pass 2: pairwise swaps
            for src in range(gpu_num):
                for dst in range(src + 1, gpu_num):
                    for m1 in list(placement[src]):
                        for m2 in list(placement[dst]):
                            r1, r2 = m1.req_rate / m1.slo, m2.req_rate / m2.slo
                            fs = free[src] + m1.model_size - m2.model_size
                            fd = free[dst] + m2.model_size - m1.model_size
                            if fs <= 0 or fd <= 0:
                                continue
                            others = max(
                                (kvpr(load[g], free[g]) for g in range(gpu_num)
                                 if g not in (src, dst)), default=0.0)
                            new_max = max(
                                kvpr(load[src] - r1 + r2, fs),
                                kvpr(load[dst] - r2 + r1, fd),
                                others,
                            )
                            if new_max < cur_max - 1e-12:
                                placement[src].remove(m1); placement[src].append(m2)
                                placement[dst].remove(m2); placement[dst].append(m1)
                                load[src] += r2 - r1
                                free[src] = fs
                                load[dst] += r1 - r2
                                free[dst] = fd
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        return placement

    import random
    rng = random.Random(42)
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
        list(models),
    ]
    # Seeded random restarts for extra diversity
    for _ in range(6):
        order = list(models)
        rng.shuffle(order)
        orders.append(order)

    best_placement, best_max = None, float('inf')
    best_assign = None
    for order in orders:
        placement, free, load = greedy(order)
        if placement is None:
            continue
        placement = refine(placement, free, load)
        cur_max = max(kvpr(load[g], free[g]) for g in range(gpu_num))
        if cur_max < best_max:
            best_max, best_placement = cur_max, placement
            best_assign = [None] * len(models)
            for g, ms in placement.items():
                for m in ms:
                    best_assign[models.index(m)] = g

    # ---- Binary search on KVPR threshold T with greedy feasibility ----
    import random
    rng = random.Random(1234)
    n = len(models)
    if n > 0 and best_placement is not None:
        r = [m.req_rate / m.slo for m in models]
        s = [m.model_size for m in models]
        # order: by rate desc (best-fit-decreasing)
        order = sorted(range(n), key=lambda i: r[i], reverse=True)

        def try_assign(T, jitter=0.0):
            # returns assignment list if feasible under threshold T
            load = [0.0] * gpu_num
            free = [GPU_MEM_SIZE] * gpu_num
            assign = [None] * n
            for i in order:
                # candidate gpus: memory fits and budget covers r[i]
                cands = [g for g in range(gpu_num)
                         if free[g] - s[i] > 1e-9
                         and load[g] + r[i] <= T * (free[g] - s[i]) + 1e-9]
                if not cands:
                    return None
                # best-fit: minimize leftover budget T*free' - load'
                def leftover(g):
                    return T * (free[g] - s[i]) - (load[g] + r[i])
                if jitter > 0:
                    g = min(cands, key=lambda g: leftover(g) + rng.random() * jitter)
                else:
                    g = min(cands, key=leftover)
                assign[i] = g
                load[g] += r[i]
                free[g] -= s[i]
            return assign

        # upper bound: current best max (feasible), lower bound 0
        lo, hi = 0.0, best_max
        for _ in range(40):
            mid = (lo + hi) / 2.0
            assign = try_assign(mid)
            if assign is None:
                # randomized retries to escape greedy myopia
                for _ in range(5):
                    assign = try_assign(mid, jitter=mid * 0.5)
                    if assign is not None:
                        break
            if assign is not None:
                hi = mid
                best_assign = assign
            else:
                lo = mid
        if best_assign is not None:
            best_placement = {g: [] for g in range(gpu_num)}
            for i in range(n):
                best_placement[best_assign[i]].append(models[i])

    if best_placement is None:
        # No ordering fit; fall back to a best-effort placement that always
        # returns a dict (overcommit only if truly impossible).
        best_placement, _, _ = greedy(sorted(models, key=lambda m: m.model_size))
        if best_placement is None:
            placement = {g: [] for g in range(gpu_num)}
            free = [GPU_MEM_SIZE] * gpu_num
            for model in sorted(models, key=lambda m: m.model_size):
                fits = [g for g in range(gpu_num) if free[g] >= model.model_size]
                g = fits[0] if fits else min(range(gpu_num),
                                             key=lambda x: free[x])
                placement[g].append(model)
                free[g] -= model.model_size
            best_placement = placement

    return best_placement

# EVOLVE-BLOCK-END


